ROLES = {"fleet-admin": {"vehicle:read", "vehicle:command"}, "viewer": {"vehicle:read"}}

def rbac(user, action):
    return any(action in ROLES[r] for r in user["roles"])

def abac(user, action, vehicle):
    if not rbac(user, action):
        return False
    same_org = user["org"] == vehicle["owner_org"]
    if action == "vehicle:command":
        return same_org and vehicle["speed_kmh"] == 0
    return same_org

kim = {"roles": ["fleet-admin"], "org": "A렌터카"}
print(rbac(kim, "vehicle:command"))                                          # True
print(abac(kim, "vehicle:command", {"owner_org": "A렌터카", "speed_kmh": 0}))   # True
print(abac(kim, "vehicle:command", {"owner_org": "B물류", "speed_kmh": 0}))     # False
print(abac(kim, "vehicle:command", {"owner_org": "A렌터카", "speed_kmh": 60}))  # False
